/**
 * Derives the structural part of the Pro CSS from the Halo CSS, so both kits always style the same
 * classes with the same layout:
 *
 *   packages/halo/css/0*.css  →  packages/pro/css/0*.css   (generated, do not edit)
 *   packages/pro/css/90-pro-look.css                        (hand-written Pro look, wins by order)
 *
 * The rules follow reference/pro: square corners (2px on controls, round only for status dots and
 * radios), hairlines instead of shadows on in-flow surfaces, weights up to 600, sizes from the
 * density tokens, no hover lift or press scale.
 *
 *   node scripts/pro-css.ts          write
 *   node scripts/pro-css.ts --check  exit 1 when out of date (also covered by scripts/css.test.ts)
 */
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import postcss, { type Declaration, type Rule } from "postcss";
import { ROOT } from "./tokens.ts";

const HALO = join(ROOT, "packages", "halo", "css");
const PRO = join(ROOT, "packages", "pro", "css");

/** Selectors that keep round shapes in Pro: status dots, radios, spinners. */
const ROUND = /(dot|shape|radio|typing|spin|unread|pulse|today::after|live::after|-ring\b)/;

const SIZE: Record<string, string> = {
  "40px": "28px",
  "32px": "24px",
  "28px": "22px",
  "20px": "18px",
  "16px": "14px",
};
const LINE: Record<string, string> = {
  "44px": "32px",
  "36px": "28px",
  "34px": "28px",
  "26px": "24px",
  "22px": "20px",
};
const WEIGHT: Record<string, string> = { "800": "600", "700": "600", "600": "500" };

function selectorOf(d: Declaration): string {
  const r = d.parent as Rule | undefined;
  return r && r.type === "rule" ? r.selector : "";
}

function radius(value: string, sel: string): string {
  if (ROUND.test(sel) && /50%|999px|var\(--radius-pill\)/.test(value)) return "var(--radius-full)";
  return value
    .replace(/calc\(var\(--radius-(?:lg|xl|md)\) - \d+px\)/g, "0")
    .replace(/(^|\s)50%/g, "$1var(--radius-1)")
    .replace(/(^|\s)(\d+(?:\.\d+)?)px/g, (m, pre: string, n: string) =>
      Number(n) >= 4 ? `${pre}var(--radius-1)` : m,
    );
}

function font(value: string): string {
  // `600 13px/18px var(--font-sans)` → weight, size and line height mapped to the Pro scale
  return value.replace(
    /^(\d{3})\s+(\d+px)(?:\s*\/\s*(\d+px))?/,
    (_m, w: string, size: string, lh?: string) =>
      `${WEIGHT[w] ?? w} ${SIZE[size] ?? size}${lh ? `/${LINE[lh] ?? lh}` : ""}`,
  );
}

function shadow(value: string): string {
  return value
    .replace(/var\(--shadow-card\)/g, "0 0 0 var(--line-width) var(--line)")
    .replace(/var\(--shadow-lift\)/g, "0 0 0 var(--line-width) var(--line-strong)")
    .replace(/var\(--shadow-float\)/g, "var(--shadow-float), 0 0 0 var(--line-width) var(--line)");
}

function control(value: string): string {
  return value === "40px" || value === "36px"
    ? "var(--density-control)"
    : value === "32px"
      ? "var(--control-sm)"
      : value === "60px"
        ? "var(--topbar-h)"
        : value;
}

export function derive(css: string, from: string): string {
  const root = postcss.parse(css, { from });
  root.walkDecls((d) => {
    const sel = selectorOf(d);
    switch (d.prop) {
      case "border-radius":
        d.value = radius(d.value, sel);
        break;
      case "font":
        d.value = font(d.value);
        break;
      case "font-weight":
        d.value = WEIGHT[d.value] ?? d.value;
        break;
      case "font-size":
        d.value = SIZE[d.value] ?? d.value;
        break;
      case "box-shadow":
        d.value = shadow(d.value);
        break;
      case "height":
      case "min-height":
        d.value = control(d.value);
        break;
      case "transform":
        // no hover lift and no press scale in Pro
        if (/:(hover|active)/.test(sel) && /translateY\(-?\d|scale\(/.test(d.value))
          d.value = "none";
        break;
    }
  });
  return (
    "/* Generated by scripts/pro-css.ts from packages/halo/css. Do not edit; the Pro look lives in 90-pro-look.css. */\n" +
    root.toString()
  );
}

export function haloFiles(): string[] {
  return readdirSync(HALO)
    .filter((f) => f.endsWith(".css"))
    .sort();
}

export function proOutputs(): { path: string; content: string }[] {
  return haloFiles().map((f) => {
    const p = join(HALO, f);
    return { path: join(PRO, f), content: derive(readFileSync(p, "utf8"), p) };
  });
}

export function proStale(): string[] {
  return proOutputs()
    .filter((o) => !existsSync(o.path) || readFileSync(o.path, "utf8") !== o.content)
    .map((o) => o.path.slice(ROOT.length + 1));
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes("--check")) {
    const s = proStale();
    if (s.length) {
      console.error(`Derived Pro CSS is out of date (run \`pnpm tokens\`):\n  ${s.join("\n  ")}`);
      process.exit(1);
    }
  } else {
    for (const o of proOutputs()) {
      writeFileSync(o.path, o.content);
      console.log(`wrote ${o.path.slice(ROOT.length + 1)}`);
    }
  }
}
